20: const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
21: const screens = ['welcome','profiles','dashboard','games','plus','store','downloads'];
22: let currentScreen='welcome', currentFilter='all', storeCategory='Featured', sortDescending=false;
23: let membership=false, queue=[], timers=new Map(), toastTimer, gameTimer=null, gameScore=0, gameLive=false;
24: const topbar=$('#topbar'), footer=$('#system-footer'), modalBackdrop=$('#modal-backdrop'), modalContent=$('#modal-content');
