68: function validateUsername(value){
69:  const name=value.trim();if(!/^[A-Za-z0-9_]{3,16}$/.test(name))return 'Use 3–16 characters: letters, numbers, or underscores only.';
70:  const normalized=name.toLowerCase().replace(/[013457@$]/g,char=>({'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t','@':'a','$':'s'}[char])).replace(/[^a-z]/g,'');
71:  const blocked=['fuck','shit','bitch','cunt','dick','piss',' bastard','asshole','nigger','faggot','retard','whore','slut','porn'];
72:  if(blocked.some(word=>normalized.includes(word.trim())))return 'That username isn’t available. Please choose a kinder name.';
73:  if(/^(admin|moderator|playstation|sony|official)$/i.test(name))return 'Please choose a username that doesn’t impersonate an official account.';
74:  return '';
75: }
