/* Player signup and community */
.profile-screen{padding:42px 6vw;isolation:isolate}
.signup-layout{position:relative;z-index:1;width:min(1040px,100%);min-height:calc(100vh - 190px);margin:0 auto;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(320px,.85fr);align-items:center;gap:clamp(34px,7vw,100px)}
.signup-panel{width:100%;max-width:470px;padding:34px;border:1px solid rgba(151,190,240,.15);border-radius:14px;background:linear-gradient(145deg,rgba(18,34,55,.91),rgba(10,21,36,.87));box-shadow:0 28px 80px rgba(0,0,0,.24);backdrop-filter:blur(16px)}
.signup-panel>.eyebrow{margin-bottom:13px}.signup-panel h1{font:700 clamp(34px,4vw,48px)/1.04 var(--display);letter-spacing:-.06em;margin:0 0 11px}.signup-panel>p.muted{font-size:13px;line-height:1.6;margin:0 0 28px;max-width:355px}
.signup-label,.avatar-picker-label{display:block;color:#e0e9f6;font-weight:600;font-size:11px;margin:0 0 9px}.username-input{width:100%;min-height:45px;padding:0 13px;color:#f5f8ff;background:rgba(4,13,24,.72);border:1px solid rgba(161,190,226,.2);border-radius:6px;outline:none;font:500 13px var(--font);transition:border-color .2s,box-shadow .2s}.username-input:focus{border-color:#72b9ff;box-shadow:0 0 0 3px rgba(79,158,242,.12)}.username-input[aria-invalid=true]{border-color:#ff858c}.signup-help{display:block;color:#8293aa;font-size:10px;margin:7px 0 20px}.avatar-picker-label{margin-bottom:10px}.avatar-picker{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:17px}.avatar-option{width:44px;height:44px;border:1px solid rgba(159,190,230,.16);border-radius:9px;background:rgba(255,255,255,.045);font-size:22px;transition:.18s}.avatar-option:hover{transform:translateY(-2px);background:rgba(101,165,237,.14)}.avatar-option.selected{border-color:#78bcff;background:rgba(82,153,232,.18);box-shadow:0 0 0 2px rgba(82,153,232,.12)}.signup-error{color:#ffabb0;font-size:11px;line-height:1.5;margin:0 0 12px}.signup-error[hidden]{display:none}.create-profile-btn{width:100%;justify-content:center;min-height:45px}.signup-note{font-size:9px;color:#7e8da2;line-height:1.5;margin:13px 0 0;text-align:center}
.social-preview{width:100%;padding:23px;border:1px solid rgba(151,190,240,.13);border-radius:12px;background:rgba(14,27,44,.78);box-shadow:0 22px 65px rgba(0,0,0,.17);backdrop-filter:blur(14px)}.social-card-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.social-card-head .eyebrow{margin:0 0 5px}.social-card-head h2{font:700 22px var(--display);letter-spacing:-.04em;margin:0}.social-card-head h3{font:700 13px var(--display);margin:0}.social-preview>p.muted{font-size:11px;line-height:1.55;margin:9px 0 15px}.online-count{display:flex;align-items:center;gap:6px;color:#a8e8c1;font-size:8px;letter-spacing:.13em}.online-count i,.friend-online{width:6px;height:6px;border-radius:50%;background:#67dfa1;box-shadow:0 0 8px #48d88a}.popular-list,.friends-list{display:grid;gap:7px}.popular-user,.friend-row{display:flex;align-items:center;gap:10px;min-width:0;padding:9px;border:1px solid rgba(255,255,255,.055);border-radius:7px;background:rgba(255,255,255,.025)}.avatar.social-avatar{display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px;border-radius:9px;background:linear-gradient(145deg,#294363,#18283c);font-size:18px}.social-user-info{display:flex;flex:1;min-width:0;flex-direction:column;gap:4px}.social-user-info b{overflow:hidden;color:#e8eef7;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.social-user-info small{overflow:hidden;color:#899bb1;font-size:8px;text-overflow:ellipsis;white-space:nowrap}.add-friend-btn,.remove-friend-btn{display:grid;place-items:center;flex:0 0 28px;width:28px;height:28px;border:1px solid rgba(120,180,244,.22);border-radius:7px;background:rgba(72,137,209,.1);color:#a7d2ff;font-size:17px;transition:.18s}.add-friend-btn:hover,.remove-friend-btn:hover{background:rgba(72,137,209,.25)}.add-friend-btn.is-added{color:#94e6b5;border-color:rgba(104,218,153,.25);background:rgba(58,160,103,.12)}.signup-friends{margin-top:19px;padding-top:16px;border-top:1px solid rgba(255,255,255,.08)}.signup-friends .social-card-head{margin-bottom:9px}.friend-count{display:grid;place-items:center;min-width:23px;height:23px;padding:0 6px;border:1px solid rgba(113,169,231,.18);border-radius:20px;color:#a8cfff;font-size:9px}.friend-row{padding:7px 9px}.friend-row .avatar.social-avatar{width:29px;height:29px;flex-basis:29px;font-size:16px}.friend-row .social-user-info small{display:flex;align-items:center;gap:6px}.friend-online{width:5px;height:5px}.remove-friend-btn{border:0;background:transparent;color:#7f91a8;font-size:18px}.friends-empty{margin:0;padding:12px;color:#8495aa;font-size:10px;text-align:center}.profile-console-glow{z-index:-1;pointer-events:none}
.dashboard-lower{align-items:start}.friends-widget{padding:15px;border:1px solid rgba(255,255,255,.08);border-radius:8px;background:rgba(16,29,46,.7)}.friends-widget .social-card-head{margin-bottom:10px}.friends-widget .social-card-head>div{display:grid;gap:4px}.friends-widget .social-card-head>div>b{font:700 12px var(--display)}.friends-widget .social-card-head small{color:#8c9cb1;font-size:9px}.friends-add{width:27px;height:27px;border:1px solid rgba(123,181,244,.18);border-radius:6px;background:rgba(89,153,222,.1);color:#aad4ff}.friends-widget .friend-row{background:rgba(255,255,255,.025)}.profile-modal-card{display:flex;align-items:center;gap:12px;margin:16px 0 20px;padding:12px;border:1px solid rgba(255,255,255,.09);border-radius:8px;background:rgba(255,255,255,.035)}.profile-modal-avatar{display:grid;place-items:center;width:42px;height:42px;border-radius:10px;background:#243955;font-size:23px}.profile-modal-card>div{display:grid;gap:5px}.profile-modal-card b{font-size:12px}.profile-modal-card small{color:#92a0b2;font-size:9px}.edit-name-row{display:flex;gap:8px}.edit-name-row .username-input{flex:1;min-width:0}.modal-avatar-picker{margin:9px 0 14px}.modal-avatar-picker .avatar-option{width:37px;height:37px;font-size:19px}.avatar-picker-label{margin-top:15px}.modal-social-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-top:18px}.modal-social-grid>div{min-width:0}.modal-social-grid .social-card-head{margin-bottom:8px}.modal-social-grid .popular-list,.modal-social-grid .friends-list{max-height:210px;overflow:auto}.modal-social-grid .popular-user{padding:7px}.modal-social-grid .social-user-info small{font-size:7px}.account-add-copy{margin:12px 0;padding:10px 12px;border-left:2px solid #85baff;border-radius:0 5px 5px 0;background:rgba(93,157,231,.08);color:#c6ddfa;font-size:12px}
@media(max-width:850px){.profile-screen{padding:30px 4vw}.signup-layout{gap:24px;grid-template-columns:minmax(0,1fr) minmax(280px,.9fr)}.signup-panel{padding:25px}.social-preview{padding:18px}.dashboard-lower{grid-template-columns:1fr 1fr}.friends-widget{grid-column:1/-1}}
@media(max-width:650px){.profile-screen{min-height:calc(100vh - 62px);padding:24px 16px 34px}.signup-layout{min-height:0;display:flex;flex-direction:column;align-items:stretch;gap:18px}.signup-panel{max-width:none;padding:22px 19px}.signup-panel h1{font-size:36px}.signup-panel>p.muted{margin-bottom:22px}.social-preview{padding:17px}.popular-user{padding:8px}.social-preview .social-card-head h2{font-size:19px}.dashboard-lower{grid-template-columns:1fr}.friends-widget{grid-column:auto}.modal-social-grid{grid-template-columns:1fr}.modal-social-grid .popular-list,.modal-social-grid .friends-list{max-height:165px}.modal{width:min(560px,calc(100vw - 24px));padding:22px}.edit-name-row{align-items:stretch}.account-add-copy{font-size:11px}}

