58: function renderCommunity(){
59:  const added=new Set(friendIds);
60:  const popular=$('#popular-users');if(popular)popular.innerHTML=popularUsers.map(user=>`<div class="popular-user"><span class="avatar social-avatar">${user.avatar}</span><span class="social-user-info"><b>${user.name}</b><small>${user.status}</small></span><button class="add-friend-btn ${added.has(user.id)?'is-added':''}" data-friend="${user.id}" ${added.has(user.id)?'aria-label="Remove from friends" title="Remove friend"':'aria-label="Add friend" title="Add friend"'}>${added.has(user.id)?'✓':'＋'}</button></div>`).join('');
61:  const friends=popularUsers.filter(user=>added.has(user.id));
62:  const listMarkup=friends.length?friends.map(user=>`<div class="friend-row"><span class="avatar social-avatar">${user.avatar}</span><span class="social-user-info"><b>${user.name}</b><small><i class="friend-online"></i>${user.status.split(' · ')[0]}</small></span><button class="remove-friend-btn" data-remove-friend="${user.id}" aria-label="Remove ${user.name}">×</button></div>`).join(''):'<p class="friends-empty">Your friends will show up here.</p>';
63:  ['#signup-friends-list','#dashboard-friends-list','#modal-friends-list'].forEach(selector=>{const el=$(selector);if(el)el.innerHTML=listMarkup});
64:  ['#signup-friend-count','#modal-friend-count'].forEach(selector=>{const el=$(selector);if(el)el.textContent=String(friends.length)});
65:  const dashCount=$('#dashboard-friend-count');if(dashCount)dashCount.textContent=`${friends.length} ${friends.length===1?'friend':'friends'} · ${friends.filter(user=>user.status.startsWith('Online')).length} online`;
66:  const modalPopular=$('#modal-popular-users');if(modalPopular)modalPopular.innerHTML=popularUsers.map(user=>`<div class="popular-user"><span class="avatar social-avatar">${user.avatar}</span><span class="social-user-info"><b>${user.name}</b><small>${user.status}</small></span><button class="add-friend-btn ${added.has(user.id)?'is-added':''}" data-friend="${user.id}" aria-label="${added.has(user.id)?'Remove from':'Add to'} friends">${added.has(user.id)?'✓':'＋'}</button></div>`).join('');
67: }
68: function validateUsername(value){
69:  const name=value.trim();if(!/^[A-Za-z0-9_]{3,16}$/.test(name))return 'Use 3–16 characters: letters, numbers, or underscores only.';
70:  const normalized=name.toLowerCase().replace(/[013457@$]/g,char=>({'0':'o','1':'i','3':'e','4':'a','5':'s','7':'t','@':'a','$':'s'}[char])).replace(/[^a-z]/g,'');
71:  const blocked=['fuck','shit','bitch','cunt','dick','piss',' bastard','asshole','nigger','faggot','retard','whore','slut','porn'];
72:  if(blocked.some(word=>normalized.includes(word.trim())))return 'That username isn’t available. Please choose a kinder name.';
73:  if(/^(admin|moderator|playstation|sony|official)$/i.test(name))return 'Please choose a username that doesn’t impersonate an official account.';
74:  return '';
75: }
76: function createProfile(){
77:  const input=$('#username-input'), error=$('#signup-error'), name=input.value.trim(), issue=validateUsername(name);
78:  if(issue){error.textContent=issue;error.hidden=false;input.setAttribute('aria-invalid','true');input.focus();return}
79:  input.removeAttribute('aria-invalid');error.hidden=true;
80:  playerProfile={name,avatar:selectedAvatar};saveCommunity();syncPlayerUI();showScreen('dashboard');showToast(`Welcome, ${name}! Your player profile is ready.`);
81: }
82: function saveUsername(){
83:  const input=$('#edit-username'), error=$('#modal-profile-error'), name=input.value.trim(), issue=validateUsername(name);
84:  if(issue){error.textContent=issue;error.hidden=false;input.setAttribute('aria-invalid','true');input.focus();return}
85:  input.removeAttribute('aria-invalid');error.hidden=true;playerProfile.name=name;saveCommunity();syncPlayerUI();openProfileModal();showToast(`Your username is now ${name}.`);
86: }
