129: function addDownload(game,kind='game'){
130:  if(queue.find(q=>q.name===game.name&&q.status!=='complete')){showToast(`${game.name} is already in your downloads`);showScreen('downloads');return}
131:  const entry={id:Date.now()+Math.random(),name:game.name,art:game.art||'rocket',label:game.label||'PS',size:game.size||'12.8 GB',left:game.size||'12.8 GB',progress:0,status:'active',kind};queue.unshift(entry);renderDownloads();showToast(`${game.name} added to downloads`);showScreen('downloads');
132:  const tick=()=>{if(entry.status!=='active')return;entry.progress=Math.min(100,entry.progress+Math.ceil(Math.random()*4+1));entry.left=entry.progress>75?'2.1 GB':entry.progress>45?'5.8 GB':entry.progress>15?'9.4 GB':entry.size;entry.speed=(24+Math.random()*18).toFixed(1)+' MB/s';if(entry.progress>=100){entry.status='complete';entry.left='';clearInterval(timers.get(entry.id));timers.delete(entry.id);showToast(`${entry.name} is ready to play`)}renderDownloads()};
133:  timers.set(entry.id,setInterval(tick,520));
134: }
