function launchFortnite(game){
  const best=Number(localStorage.getItem('best-'+game.id)||0);
  const playerName=escapeHTML(playerProfile?.name||'Player');
  const scene=`<div class="rift-game" id="play-area" aria-label="Rift Royale game arena"><div class="rift-game-top"><div><span class="rift-label">ELIMS</span><b id="score">0</b></div><div><span class="rift-label">SHIELD</span><b><span id="rift-shield">100</span><i class="shield-track"><i id="rift-shield-fill"></i></i></b></div><div><span class="rift-label">STORM</span><b id="rift-time">30</b></div></div><div class="rift-island"><div class="rift-sun"></div><div class="rift-mountain mountain-one"></div><div class="rift-mountain mountain-two"></div><div class="rift-building building-one"></div><div class="rift-building building-two"></div><div class="rift-building building-three"></div><div class="rift-player" id="rift-player" aria-label="${playerName} on the island"><span>${escapeHTML(playerProfile?.avatar||'🎮')}</span><small>${playerName}</small></div><div class="rift-target-layer" id="rift-target-layer"></div><div class="rift-live-message" id="rift-message">DROP IN · TAP RIFTS TO ELIMINATE</div></div><div class="rift-game-bottom"><span>◉ ZERO BUILD · SOLO</span><span>WAVE 01 <i class="rift-live-dot"></i> LIVE</span></div></div>`;
  openModal(`<div class="rift-brand-bar"><span>FORTNITE <i>×</i> PLAYSTATION</span><span>APP-MADE ISLAND · ZERO BUILD</span></div><div class="eyebrow"><i></i> NOW PLAYING · ISLAND SURVIVAL</div><h2 id="modal-title">Rift Royale</h2><p>Drop into the island, tag the rift targets and keep your shield up. Storm rifts hurt—healing shards restore your shield. You have 30 seconds to stack eliminations.</p>${scene}<div class="rift-controls"><span><b>HOW TO PLAY</b> Tap blue rifts to eliminate · purple shards to heal · avoid red storm rifts</span><span>BEST <b id="best-score">${best}</b></span></div><div class="modal-actions rift-actions"><button class="secondary-btn" data-action="close-modal">Leave island</button><button class="primary-btn" data-action="restart-fortnite">Drop again <span>↻</span></button></div>`);
  gameScore=0;gameLive=true;startFortniteRound();
}
function spawnFortniteTarget(){
  const layer=$('#rift-target-layer');if(!layer||!gameLive)return;
  const types=[['rift','✦'],['rift','✦'],['rift','✦'],['heal','＋'],['storm','!']];
  const [type,symbol]=types[Math.floor(Math.random()*types.length)];
  const target=document.createElement('button');target.className=`rift-target ${type}`;target.type='button';target.textContent=symbol;
  target.setAttribute('aria-label',type==='rift'?'Eliminate rift target':type==='heal'?'Collect shield shard':'Storm rift — avoid');
  target.style.left=(8+Math.random()*82)+'%';target.style.top=(15+Math.random()*66)+'%';
  target.addEventListener('click',event=>{event.stopPropagation();if(!gameLive)return;target.remove();if(type==='rift'){gameScore++;setScore();$('#rift-message').textContent=['NICE SHOT!','RIFT ELIMINATED','KEEP IT UP!'][Math.floor(Math.random()*3)]}else if(type==='heal'){setFortniteShield(Math.min(100,(window.fortniteShield||100)+25));$('#rift-message').textContent='SHIELD UP +25'}else{setFortniteShield(Math.max(0,(window.fortniteShield||100)-35));$('#rift-message').textContent='STORM HIT −35';if(window.fortniteShield===0)endFortniteRound('YOUR SHIELD BROKE · ISLAND LOST')}});
  layer.appendChild(target);
  const expiry=setTimeout(()=>target.remove(),1900);fortniteTargetTimers.push(expiry);
}
function setFortniteShield(value){window.fortniteShield=value;const shield=$('#rift-shield'),fill=$('#rift-shield-fill');if(shield)shield.textContent=value;if(fill)fill.style.width=value+'%'}
function startFortniteRound(){
  stopMinigame();gameLive=true;gameScore=0;setFortniteShield(100);
  const score=$('#score'),time=$('#rift-time'),layer=$('#rift-target-layer'),message=$('#rift-message');if(score)score.textContent='0';if(layer)layer.replaceChildren();if(time)time.textContent='30';if(message)message.textContent='DROP IN · TAP RIFTS TO ELIMINATE';
  let seconds=30;spawnFortniteTarget();fortniteSpawnTimer=setInterval(spawnFortniteTarget,920);
  gameTimer=setInterval(()=>{seconds--;const clock=$('#rift-time');if(clock)clock.textContent=String(seconds).padStart(2,'0');if(seconds<=0)endFortniteRound('STORM CLOSED · MATCH COMPLETE')},1000);
}
function endFortniteRound(message){
  if(!gameLive)return;gameLive=false;clearInterval(gameTimer);gameTimer=null;clearInterval(fortniteSpawnTimer);fortniteSpawnTimer=null;
  fortniteTargetTimers.forEach(clearTimeout);fortniteTargetTimers=[];$('#rift-target-layer')?.replaceChildren();const status=$('#rift-message');if(status)status.textContent=message;
  const best=Number(localStorage.getItem('best-fortnite')||0);if(gameScore>best){localStorage.setItem('best-fortnite',String(gameScore));const bestNode=$('#best-score');if(bestNode)bestNode.textContent=String(gameScore)}
}

